<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Simulador · La fotosíntesis</title>
  <style>
    :root {
      --primary: #0A3D91;
      --accent: #F47A20;
      --bg: #F7F9FC;
      --surface: #FFFFFF;
    }
    .ova-container {
      max-width: 880px;
      margin: 0 auto;
      padding: 0 16px;
    }
    .ova-card {
      background-color: var(--surface);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      padding: 24px;
      margin: 24px 0;
    }
    .ova-header {
      font-family: 'Arial', sans-serif;
      text-align: center;
      margin-bottom: 24px;
    }
    .ova-header h1 {
      font-size: 24px;
    }
    .ova-objective {
      color: var(--text);
      margin: 0 0 16px;
    }
    .ova-steps ol {
      list-style-type: decimal;
      letter-spacing: 0.5px;
    }
    .ova-btn {
      padding: 10px 24px;
      border: 1px solid var(--accent);
      background-color: var(--accent);
      color: #fff;
      border-radius: var(--radius);
      cursor: pointer;
    }
    .ova-btn--ghost {
      background-color: transparent;
      border: 1px solid var(--text);
      color: var(--text);
    }
    .ova-btn--ghost:hover {
      background-color: #f4f4f4;
    }
    .ova-reveal {
      margin-top: 16px;
    }
    .ova-progress {
      margin-top: 16px;
      border: 1px solid var(--border);
      padding: 4px;
      border-radius: var(--radius);
      overflow: hidden;
      width: 100%;
    }
    .ova-progress span {
      background-color: var(--accent);
      height: 100%;
      transition: width 0.3s ease;
    }
    #estado {
      margin-top: 16px;
      color: var(--text-muted);
    }
  </style>
</head>
<body>
  <main class="ova-container">
    <upao-header eyebrow="SIMULADOR" title="La fotosíntesis"></upao-header>
    <upao-objective>Al terminar podrás ajustar y predecir el tamaño de un parámetro relacionado con la fotosíntesis.</upao-objective>
    <section class="ova-card">
      <upao-example title='Ejemplo trabajado'><upao-steps><ol>
        <li>Configura las condiciones experimentales para observar la fotosíntesis.</li>
        <li>Mide el CO2 absorbido por la planta y compara con las condiciones iniciales.</li>
      </ol></upao-steps></upao-example>
      <upao-figure caption='Ciclo de fotosíntesis'>SVG o imagen con alt</upao-figure>
      <upao-question number='1' prompt='Ajusta la intensidad de luz solar:'>
        <upao-choice value='A' correct='false' feedback='La planta absorberá menos CO2 en luz débil. Aumenta la iluminación.' group='q1'>Reducción de luz solar</upao-choice>
        <upao-choice value='B' correct='true' feedback='¡Correcto! El aumento de luz solar aumentará la absorción de CO2 por la planta.' group='q1'>Aumento de luz solar</upao-choice>
        <upao-choice value='C' correct='false' feedback='La absorción de CO2 por la planta no cambiará con la iluminación. Mantén las condiciones iniciales.' group='q1'>Mantener las condiciones actuales</upao-choice>
      </upao-question>
      <upao-progress id='p' current='50' total='100' show-fraction aria-label="Progreso de la actividad"></upao-progress>
      <p id="estado" aria-live="polite" class="ova-muted"></p>
    </section>
    <button class="ova-btn" id="continuar" disabled>Continuar →</button>
  </main>
  <script>
    (function() {
      const continuar = document.getElementById('continuar');
      const estado = document.getElementById('estado');
      let currentProgress = 50;

      upaoProgress.addEventListener('upao-nav-change', event => {
        if (event.index === 2) {
          continuar.disabled = false;
        } else {
          continuar.disabled = true;
        }
      });

      continuar.addEventListener('click', () => {
        continuar.disabled = true;
        estado.textContent = '✓ Avance exitoso';
        currentProgress += 50;
        document.querySelector('.ova-progress span').style.width = `${currentProgress}%`;
      });
    })();
  </script>
</body>
</html>
```
